query:
mutation Drop1c($p0: ProductSetInput!, $p1: ProductSetInput!, $p2: ProductSetInput!, $p3: ProductSetInput!, $p4: ProductSetInput!, $p5: ProductSetInput!) {
  p0: productSet(synchronous: true, input: $p0) { product { id handle status variantsCount { count } } userErrors { field message code } }
  p1: productSet(synchronous: true, input: $p1) { product { id handle status variantsCount { count } } userErrors { field message code } }
  p2: productSet(synchronous: true, input: $p2) { product { id handle status variantsCount { count } } userErrors { field message code } }
  p3: productSet(synchronous: true, input: $p3) { product { id handle status variantsCount { count } } userErrors { field message code } }
  p4: productSet(synchronous: true, input: $p4) { product { id handle status variantsCount { count } } userErrors { field message code } }
  p5: productSet(synchronous: true, input: $p5) { product { id handle status variantsCount { count } } userErrors { field message code } }
}
